      'gu':
          '• પુરવઠામાં ઘટાડો થવાને કારણે છેલ્લા \nઅઠવાડિયામાં ઘઉંના ભાવમાં 5%નો વધારો થયો છે.\n• ચોખા સતત માંગ સાથે સ્થિર રહે છે.\n• મોસમી ફેરફારોને કારણે આગામી \nઅઠવાડિયામાં મકાઈના ભાવમાં વધારો થવાની ધારણા છે.',
      'hi':
          '• आपूर्ति कम होने के कारण पिछले सप्ताह गेहूं की कीमतों में 5% की वृद्धि हुई है। • चावल की मांग स्थिर बनी हुई है। • मौसमी बदलावों के कारण आने वाले सप्ताहों में मक्का की कीमतों में वृद्धि होने की उम्मीद है।',
      'ml':
          '• കഴിഞ്ഞ ആഴ്ചയിൽ ഗോതമ്പ് വിലയിൽ 5% വർദ്ധനവുണ്ടായി, കാരണം ലഭ്യത കുറഞ്ഞു.\n• അരിയുടെ ആവശ്യകത സ്ഥിരമായി തുടരുന്നു.\n• സീസണൽ മാറ്റങ്ങൾ കാരണം വരും ആഴ്ചകളിൽ ചോളം വില ഉയരുമെന്ന് പ്രതീക്ഷിക്കുന്നു.',
      'mr':
          '• पुरवठ्यात घट झाल्यामुळे गेल्या आठवड्यात गव्हाच्या किमती ५% ने वाढल्या आहेत.\n• मागणीत सातत्य राहिल्याने तांदूळ स्थिर आहे.\n• हंगामी बदलांमुळे येत्या आठवड्यात मक्याच्या किमती वाढण्याची अपेक्षा आहे.',
      'or':
          '• ଯୋଗାଣ ହ୍ରାସ ଯୋଗୁଁ ଗତ \nସପ୍ତାହରେ ଗହମ ମୂଲ୍ୟ 5% ବୃଦ୍ଧି ପାଇଛି।\n• ଚାହିଦା ସ୍ଥିର ରହିବା ସହିତ ଚାଉଳ ସ୍ଥିର ରହିଛି।\n• ଋତୁ ପରିବର୍ତ୍ତନ ଯୋଗୁଁ ଆଗାମୀ \nସପ୍ତାହଗୁଡ଼ିକରେ ମକା ମୂଲ୍ୟ ବୃଦ୍ଧି ପାଇବାର ଆଶା କରାଯାଉଛି।',
      'ta':
          '• கடந்த \nவாரத்தில் கோதுமை விலைகள் குறைந்ததால் 5% அதிகரித்துள்ளன.\n• அரிசி நிலையான தேவையுடன் நிலையாக உள்ளது. \n• பருவகால மாற்றங்கள் காரணமாக வரும் \nவாரங்களில் மக்காச்சோள விலைகள் உயரும் என்று எதிர்பார்க்கப்படுகிறது.',
      'te':
          '• సరఫరా తగ్గడం వల్ల గత వారంలో గోధుమ ధరలు 5% పెరిగాయి.\n• బియ్యం స్థిరమైన డిమాండ్‌తో స్థిరంగా ఉన్నాయి.\n• కాలానుగుణ మార్పుల కారణంగా రాబోయే వారాలలో మొక్కజొన్న ధరలు పెరిగే అవకాశం ఉంది.',
