      'gu':
          'ઉત્પાદકતા વધારવા માટે પોષક તત્વો અને ખાતરો માટે પાકવાર ભલામણો સાથે ખેડૂતોને માટી આરોગ્ય કાર્ડ પૂરા પાડે છે.',
      'hi':
          'उत्पादकता में सुधार के लिए पोषक तत्वों और उर्वरकों के लिए फसलवार सिफारिशों के साथ किसानों को मृदा स्वास्थ्य कार्ड प्रदान करता है।',
      'ml':
          'ഉൽപ്പാദനക്ഷമത മെച്ചപ്പെടുത്തുന്നതിനായി പോഷകങ്ങളും വളങ്ങളും നൽകുന്നതിനുള്ള വിള തിരിച്ചുള്ള ശുപാർശകൾ അടങ്ങിയ മണ്ണ് ആരോഗ്യ കാർഡുകൾ കർഷകർക്ക് നൽകുന്നു.',
      'mr':
          'उत्पादकता सुधारण्यासाठी पोषक तत्वे आणि खतांसाठी पीकनिहाय शिफारसींसह शेतकऱ्यांना मृदा आरोग्य कार्ड प्रदान करते.',
      'or':
          'ଚାଷୀମାନଙ୍କୁ ଫସଲ ଅନୁଯାୟୀ ପୋଷକ ତତ୍ତ୍ୱ ଏବଂ ସାର ପାଇଁ ଉତ୍ପାଦନ ବୃଦ୍ଧି ପାଇଁ ସୁପାରିଶ ସହିତ ମୃତ୍ତିକା ସ୍ୱାସ୍ଥ୍ୟ କାର୍ଡ ପ୍ରଦାନ କରେ।',
      'ta':
          'உற்பத்தித்திறனை மேம்படுத்துவதற்காக ஊட்டச்சத்துக்கள் மற்றும் உரங்களுக்கான பயிர் வாரியான பரிந்துரைகளுடன் விவசாயிகளுக்கு மண் சுகாதார அட்டைகளை வழங்குகிறது.',
      'te':
          'ఉత్పాదకతను మెరుగుపరచడానికి పోషకాలు మరియు ఎరువుల కోసం పంటల వారీగా సిఫార్సులతో రైతులకు సాయిల్ హెల్త్ కార్డులను అందిస్తుంది.',
      'ur':
          'پیداواری صلاحیت کو بہتر بنانے کے لیے کاشتکاروں کو غذائی اجزاء اور کھادوں کے لیے فصل کے لحاظ سے سفارشات کے ساتھ مٹی کے صحت کارڈ فراہم کرتا ہے۔',
    },
