          'ജൈവകൃഷി രീതികൾ പ്രോത്സാഹിപ്പിക്കുകയും മണ്ണിന്റെ ആരോഗ്യം മെച്ചപ്പെടുത്താനും വളങ്ങളുടെയും കാർഷിക രാസവസ്തുക്കളുടെയും ആശ്രയത്വം കുറയ്ക്കാനും കർഷകരെ സഹായിക്കുകയും ചെയ്യുന്നു.',
      'mr':
          'सेंद्रिय शेती पद्धतींना प्रोत्साहन देते आणि शेतकऱ्यांना मातीचे आरोग्य सुधारण्यास आणि खते आणि कृषी रसायनांवरील अवलंबित्व कमी करण्यास मदत करते.',
      'or':
          'ଜୈବିକ କୃଷି ପଦ୍ଧତିକୁ ପ୍ରୋତ୍ସାହିତ କରେ ଏବଂ ଚାଷୀମାନଙ୍କୁ ମାଟି ସ୍ୱାସ୍ଥ୍ୟ ଉନ୍ନତ କରିବାରେ ଏବଂ ସାର ଏବଂ କୃଷି ରାସାୟନିକ ପଦାର୍ଥ ଉପରେ ନିର୍ଭରଶୀଳତା ହ୍ରାସ କରିବାରେ ସାହାଯ୍ୟ କରେ।',
      'ta':
          'இயற்கை விவசாய முறைகளை ஊக்குவித்து, விவசாயிகள் மண்ணின் ஆரோக்கியத்தை மேம்படுத்தவும், உரங்கள் மற்றும் விவசாய இரசாயனங்கள் மீதான சார்பைக் குறைக்கவும் உதவுகிறது.',
      'te':
          'సేంద్రీయ వ్యవసాయ పద్ధతులను ప్రోత్సహిస్తుంది మరియు రైతులు నేల ఆరోగ్యాన్ని మెరుగుపరచడంలో మరియు ఎరువులు మరియు వ్యవసాయ రసాయనాలపై ఆధారపడటాన్ని తగ్గించడంలో సహాయపడుతుంది.',
