          'ജൈവകൃഷി രീതികൾക്ക് പുതിയ സബ്‌സിഡി പ്രഖ്യാപിച്ചു. അപേക്ഷിക്കാനുള്ള അവസാന തീയതി ജൂൺ 15 ആണ്. വിശദാംശങ്ങൾ കാണാൻ ടാപ്പ് ചെയ്യുക.',
      'mr':
          'सेंद्रिय शेती पद्धतींसाठी नवीन अनुदान जाहीर. अर्ज करण्याची अंतिम तारीख १५ जून आहे. तपशील पाहण्यासाठी टॅप करा.',
      'or':
          'ଜୈବିକ କୃଷି ପଦ୍ଧତି ପାଇଁ ନୂତନ ସବସିଡି ଘୋଷଣା କରାଯାଇଛି। ଆବେଦନର ଶେଷ ତାରିଖ ଜୁନ୍ 15 ତାରିଖ। ବିବରଣୀ ଦେଖିବା ପାଇଁ ଟ୍ୟାପ୍ କରନ୍ତୁ।',
      'ta':
          'இயற்கை வேளாண்மை முறைகளுக்கு புதிய மானியம் அறிவிக்கப்பட்டுள்ளது. விண்ணப்பிப்பதற்கான கடைசி தேதி ஜூன் 15. விவரங்களைப் பார்க்க தட்டவும்.',
      'te':
          'సేంద్రీయ వ్యవసాయ పద్ధతులకు కొత్త సబ్సిడీ ప్రకటించబడింది. దరఖాస్తు గడువు జూన్ 15. వివరాలను వీక్షించడానికి నొక్కండి.',
      'ur':
          'نامیاتی کاشتکاری کے طریقوں کے لیے نئی سبسڈی کا اعلان۔ درخواست کی آخری تاریخ 15 جون ہے۔ تفصیلات دیکھنے کے لیے تھپتھپائیں۔',
    },
