    'iughloqk': {
      'en':
          'Early signs of aphid infestation detected in your tomato crop. Consider preventive measures to avoid spread.',
      'bn':
          'আপনার টমেটো ফসলে জাবপোকার আক্রমণের প্রাথমিক লক্ষণ সনাক্ত করা হয়েছে। বিস্তার রোধে প্রতিরোধমূলক ব্যবস্থা বিবেচনা করুন।',
      'gu':
          'તમારા ટામેટાંના પાકમાં એફિડના ઉપદ્રવના પ્રારંભિક સંકેતો જોવા મળે છે. ફેલાવો ટાળવા માટે નિવારક પગલાંનો વિચાર કરો.',
      'hi':
