      'ml':
          'നിങ്ങളുടെ തക്കാളി കൃഷിയിൽ മുഞ്ഞയുടെ ആക്രമണത്തിന്റെ ആദ്യ ലക്ഷണങ്ങൾ കണ്ടെത്തിയിട്ടുണ്ട്. പടരാതിരിക്കാൻ പ്രതിരോധ നടപടികൾ പരിഗണിക്കുക.',
      'mr':
          'तुमच्या टोमॅटो पिकात मावा किडीच्या प्रादुर्भावाची सुरुवातीची लक्षणे आढळली. पसरू नये म्हणून प्रतिबंधात्मक उपायांचा विचार करा.',
      'or':
          'ଆପଣଙ୍କ ଟମାଟୋ ଫସଲରେ ଏଫଡ୍ ଆକ୍ରମଣର ପ୍ରାରମ୍ଭିକ ଲକ୍ଷଣ ଚିହ୍ନଟ ହୋଇଛି। ବ୍ୟାପିବାକୁ ଏଡାଇବା ପାଇଁ ପ୍ରତିଷେଧକ ପଦକ୍ଷେପ ବିଷୟରେ ବିଚାର କରନ୍ତୁ।',
      'ta':
          'உங்கள் தக்காளி பயிரில் அசுவினி தொற்றின் ஆரம்ப அறிகுறிகள் கண்டறியப்பட்டுள்ளன. பரவுவதைத் தவிர்க்க தடுப்பு நடவடிக்கைகளைக் கவனியுங்கள்.',
      'te':
          'మీ టమోటా పంటలో పురుగు ముట్టడి యొక్క ప్రారంభ సంకేతాలు గుర్తించబడ్డాయి. వ్యాప్తి చెందకుండా ఉండటానికి నివారణ చర్యలను పరిగణించండి.',
